export enum RoomType {
  GIRLS = 'Girls Room',
  SINGLE = 'Single Room',
  FAMILY = 'Family Room',
  BACHELOR = 'Bachelor Room',
}

export type Language = 'EN' | 'HI';

export interface Listing {
  id: string;
  type: RoomType;
  rentPrice: number;
  locality: string;
  address: string;
  amenities: string[];
  contactPerson: string;
  contactNumber: string;
  imageUrl: string;
  isVerified: boolean;
  ownerId?: string;
}

export interface Booking {
  id: string;
  listingId: string;
  customerName: string;
  customerPhone: string;
  status: 'PENDING' | 'APPROVED' | 'REJECTED';
  date: string;
  listingDetails?: Listing;
}

export interface FilterState {
  maxPrice: number;
  roomType: RoomType | 'ALL';
  locality: string | 'ALL';
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  isThinking?: boolean;
}

export type ViewState = 'LANDING' | 'ADMIN' | 'CUSTOMER' | 'OWNER';

import React from 'react';
import { Home, ShieldCheck, LogOut, Languages } from 'lucide-react';
import { Language } from '../types';
import { translations } from '../translations';

interface HeaderProps {
  onLogout: () => void;
  isSubscribed: boolean;
  language: Language;
  setLanguage: (lang: Language) => void;
}

const Header: React.FC<HeaderProps> = ({ onLogout, isSubscribed, language, setLanguage }) => {
  const t = translations[language];

  return (
    <header className="bg-white border-b border-gray-200 sticky top-0 z-50">
      <div className="max-w-6xl mx-auto px-4 h-16 flex items-center justify-between">

        {/* Logo Area */}
        <div className="flex items-center space-x-2.5">
          <div className="bg-orange-600 p-1.5 rounded-lg text-white shadow-sm">
            <Home size={22} />
          </div>
          <div>
            <h1 className="text-xl font-extrabold text-gray-900 tracking-tight leading-none">
              Room<span className="text-orange-600">Saathi</span>
            </h1>
            <p className="text-[10px] text-gray-400 font-medium tracking-wide uppercase">{t.appTagline}</p>
          </div>
        </div>

        {/* Actions */}
        <div className="flex items-center gap-2 sm:gap-4">
          {/* Language Toggle */}
          <button 
            onClick={() => setLanguage(language === 'EN' ? 'HI' : 'EN')}
