export default Header;

import React, { useState, useMemo } from 'react';
import Header from './components/Header';
import Footer from './components/Footer';
import FilterBar from './components/FilterBar';
import ListingCard from './components/ListingCard';
import AIAssistant from './components/AIAssistant';
import SubscriptionGate from './components/SubscriptionGate';
import AdminListingForm from './components/AdminListingForm';
import AdminDashboard from './components/AdminDashboard';
import OwnerDashboard from './components/OwnerDashboard';
import LandingPage from './components/LandingPage';
import BookingModal from './components/BookingModal';
import { MOCK_LISTINGS } from './constants';
import { FilterState, Listing, ViewState, Booking, Language } from './types';
import { translations } from './translations';
import { SearchX } from 'lucide-react';

function App() {
  const [currentView, setCurrentView] = useState<ViewState>('LANDING');
  const [language, setLanguage] = useState<Language>('HI');
  const t = translations[language];

  const [listings, setListings] = useState<Listing[]>(MOCK_LISTINGS || []);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [filters, setFilters] = useState<FilterState>({
    maxPrice: 8000,
    roomType: 'ALL',
    locality: 'ALL'
  });

  const [isSubscribed, setIsSubscribed] = useState(false);
  const [showAddForm, setShowAddForm] = useState(false);
  const [editingListing, setEditingListing] = useState<Listing | null>(null);
  const [bookingListing, setBookingListing] = useState<Listing | null>(null);

  const handleAddListing = (newListing: Listing) => {
    setListings(prev => [newListing, ...prev]);
    setShowAddForm(false);
  };

  const handleUpdateListing = (updatedListing: Listing) => {
    setListings(prev => prev.map(l => l.id === updatedListing.id ? updatedListing : l));
    setEditingListing(null);
  };

  const handleDeleteListing = (id: string) => {
    if (confirm(language === 'HI' ? 'क्या आप वाकई इस कमरे को हटाना चाहते हैं?' : 'Are you sure you want to delete this room?')) {
      setListings(prev => prev.filter(l => l.id !== id));
    }
  };

  const handleCreateBooking = (customerName: string, customerPhone: string) => {
    if (!bookingListing) return;
    const newBooking: Booking = {
      id: Date.now().toString(),
      listingId: bookingListing.id,
      customerName,
      customerPhone,
      status: 'PENDING',
      date: new Date().toISOString()
    };
    setBookings(prev => [newBooking, ...prev]);
    setBookingListing(null);
    alert(language === 'HI' ? 'बुकिंग अनुरोध भेज दिया गया है! एडमिन आपसे संपर्क करेंगे।' : 'Booking Request Sent! Admin will contact you.');
  };

  const handleUpdateBookingStatus = (id: string, status: 'APPROVED' | 'REJECTED') => {
    setBookings(prev => prev.map(b => b.id === id ? { ...b, status } : b));
  };

  const filteredListings = useMemo(() => {
    if (!listings) return [];
    return listings.filter(listing => {
      if (listing.rentPrice > filters.maxPrice) return false;
      if (filters.roomType !== 'ALL' && listing.type !== filters.roomType) return false;
      if (filters.locality !== 'ALL' && listing.locality !== filters.locality) return false;
      return true;
    });
  }, [filters, listings]);

  if (currentView === 'LANDING') {
    return <LandingPage onNavigate={setCurrentView} />;
  }

  if (currentView === 'ADMIN') {
    return (
      <>
        <AdminDashboard 
          listings={listings}
          bookings={bookings}
          onAdd={() => setShowAddForm(true)}
          onEdit={(l) => setEditingListing(l)}
          onDelete={handleDeleteListing}
          onUpdateBookingStatus={handleUpdateBookingStatus}
          onLogout={() => setCurrentView('LANDING')}
        />
        {(showAddForm || editingListing) && (
           <AdminListingForm 
            listing={editingListing}
            onClose={() => { setShowAddForm(false); setEditingListing(null); }} 
            onSubmit={editingListing ? handleUpdateListing : handleAddListing} 
           />
        )}
      </>
    );
  }

  if (currentView === 'OWNER') {
    return (
      <>
        <OwnerDashboard 
          listings={listings}
          onAdd={() => setShowAddForm(true)}
          onLogout={() => setCurrentView('LANDING')}
        />
        {showAddForm && (
           <AdminListingForm 
            onClose={() => setShowAddForm(false)} 
            onSubmit={handleAddListing} 
           />
        )}
      </>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      <Header 
        onLogout={() => setCurrentView('LANDING')} 
        isSubscribed={isSubscribed}
        language={language}
        setLanguage={setLanguage}
      />

      {!isSubscribed ? (
        <SubscriptionGate onSubscribe={() => setIsSubscribed(true)} language={language} />
      ) : (
        <main className="max-w-6xl mx-auto px-4 pt-8 pb-12 flex-grow w-full">
          <div className="mb-8">
            <h2 className="text-3xl font-bold text-gray-800 mb-2">
              {language === 'HI' ? 'कवर्धा में कमरे खोजें' : 'Find Rooms in Kawardha'}
            </h2>
            <p className="text-gray-500">
              {language === 'HI' ? 'वेरिफाइड पीजी, फ्लैट और कमरे देखें। विश्वास के साथ सीधे बुकिंग करें।' : 'Browse verified PGs, flats, and rooms. Book directly with confidence.'}
            </p>
          </div>

          <FilterBar filters={filters} setFilters={setFilters} />

          <div className="mb-4 flex items-center justify-between">
            <p className="text-sm text-gray-500">
              {language === 'HI' ? 'कुल ' : 'Showing '} 
              <span className="font-bold text-gray-900">{filteredListings.length}</span> 
              {language === 'HI' ? ' परिणाम मिले' : ' premium results'}
            </p>
          </div>

          {filteredListings.length > 0 ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {filteredListings.map(listing => (
                <ListingCard 
                  key={listing.id} 
                  listing={listing} 
                  isAdmin={false} 
                  onBook={() => setBookingListing(listing)}
                  language={language}
                />
              ))}
            </div>
          ) : (
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-16 text-center flex flex-col items-center">
              <div className="bg-gray-50 p-6 rounded-full mb-6">
                <SearchX size={48} className="text-gray-400" />
              </div>
              <h3 className="text-xl font-bold text-gray-800 mb-2">{t.noRooms}</h3>
              <button 
                onClick={() => setFilters({ maxPrice: 10000, roomType: 'ALL', locality: 'ALL' })}
                className="text-orange-600 font-bold hover:underline"
              >
                {t.clearFilters}
              </button>
            </div>
          )}
        </main>
      )}

      <Footer />

      {bookingListing && (
        <BookingModal 
          listing={bookingListing} 
          onClose={() => setBookingListing(null)} 
          onConfirm={handleCreateBooking}
        />
      )}

      {isSubscribed && <AIAssistant />}
    </div>
  );
}

export default App;

import React, { useState } from 'react';
import { Listing, RoomType, Language } from '../types';
import { MapPin, Phone, CheckCircle, Wifi, Zap, Coffee, Edit, Trash2, CalendarCheck } from 'lucide-react';
import { translations } from '../translations';

interface ListingCardProps {
  listing: Listing;
  isAdmin?: boolean;
  onEdit?: () => void;
  onDelete?: () => void;
  onBook?: () => void;
  language?: Language;
}

const ListingCard: React.FC<ListingCardProps> = ({ listing, isAdmin, onEdit, onDelete, onBook, language = 'HI' }) => {
  const [showContact, setShowContact] = useState(false);
  const t = translations[language];

  const getAmenityIcon = (amenity: string) => {
    const lower = amenity.toLowerCase();
    if (lower.includes('wifi')) return <Wifi size={14} />;
    if (lower.includes('water') || lower.includes('electricity')) return <Zap size={14} />;
    if (lower.includes('food')) return <Coffee size={14} />;
    return <CheckCircle size={14} />;
  };

  const getBadgeColor = (type: RoomType) => {
    switch(type) {
        case RoomType.GIRLS: return 'bg-pink-500';
        case RoomType.FAMILY: return 'bg-purple-600';
        case RoomType.BACHELOR: return 'bg-blue-500';
        default: return 'bg-orange-500';
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-md overflow-hidden hover:shadow-lg transition-shadow border border-gray-100 flex flex-col h-full relative group">

      {isAdmin && (
        <div className="absolute top-2 left-2 z-10 flex gap-2">
          <button onClick={onEdit} className="bg-blue-600 text-white p-2 rounded-full shadow hover:bg-blue-700 transition-colors"><Edit size={16} /></button>
          <button onClick={onDelete} className="bg-red-600 text-white p-2 rounded-full shadow hover:bg-red-700 transition-colors"><Trash2 size={16} /></button>
        </div>
      )}

      <div className="relative h-48">
        <img src={listing.imageUrl} alt={listing.type} className="w-full h-full object-cover" />
        <div className="absolute top-3 right-3 bg-white/90 backdrop-blur px-3 py-1 rounded-full text-sm font-bold text-gray-800 shadow-sm">
          ₹{listing.rentPrice}/mo
        </div>
        <div className="absolute bottom-3 left-3">
          <span className={`px-2 py-1 text-xs font-semibold rounded text-white ${getBadgeColor(listing.type)}`}>
            {listing.type}
          </span>
          {listing.isVerified && (
            <span className="ml-2 px-2 py-1 text-xs font-semibold rounded bg-green-500 text-white flex items-center inline-flex">
              <CheckCircle size={12} className="mr-1" /> {t.verified}
            </span>
          )}
        </div>
      </div>

      <div className="p-4 flex-1 flex flex-col">
        <div className="flex-1">
          <h3 className="text-lg font-bold text-gray-900 mb-1">{listing.locality}</h3>
          <div className="flex items-start text-gray-500 text-sm mb-3">
            <MapPin size={16} className="mr-1 mt-0.5 flex-shrink-0" />
            <p>{listing.address}</p>
          </div>

          <div className="flex flex-wrap gap-2 mb-4">
            {listing.amenities.map((amenity, index) => (
              <span key={index} className="inline-flex items-center bg-gray-50 text-gray-600 text-xs px-2 py-1 rounded border border-gray-200">
                <span className="mr-1.5 text-orange-500">{getAmenityIcon(amenity)}</span>
                {amenity}
              </span>
            ))}
          </div>
        </div>

        <div className="border-t pt-3 mt-2 space-y-2">
           {!isAdmin && onBook && (
             <button onClick={onBook} className="w-full bg-orange-600 text-white py-2 rounded-lg font-medium hover:bg-orange-700 transition-colors flex items-center justify-center gap-2 shadow-orange-200 shadow-md">
                <CalendarCheck size={18} /> {t.bookInterest}
             </button>
           )}

          {!showContact ? (
            <button onClick={() => setShowContact(true)} className="w-full bg-gray-100 text-gray-700 py-2 rounded-lg font-medium hover:bg-gray-200 transition-colors flex items-center justify-center text-sm">
              <Phone size={16} className="mr-2" /> {t.viewContact}
            </button>
          ) : (
            <div className="bg-green-50 border border-green-200 rounded-lg p-3 text-center animate-fade-in">
              <p className="text-xs text-green-800 font-medium mb-1">Owner: {listing.contactPerson}</p>
              <a href={`tel:${listing.contactNumber}`} className="text-lg font-bold text-green-700 block hover:underline">
                {listing.contactNumber}
              </a>
              <p className="text-[10px] text-gray-500 mt-1">{language === 'HI' ? 'कॉल करते समय "रूम साथी" का नाम लें।' : 'Mention "Room Saathi" when calling.'}</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ListingCard;

